diff --git a/components/canvas/floating/FloatingFrameActions.tsx b/components/canvas/floating/FloatingFrameActions.tsx
new file mode 100644
index 0000000..b3d85cb
--- /dev/null
+++ b/components/canvas/floating/FloatingFrameActions.tsx
@@ -0,0 +1,687 @@
+'use client';
+
+import { useCallback, useRef, useEffect, useState, useTransition } from 'react';
+import { Download, Share, Frame, Trash2, Check } from 'lucide-react';
+import { toast } from 'sonner';
+import { useTranslations, useLocale } from 'next-intl';
+import { useForm } from 'react-hook-form';
+import { zodResolver } from '@hookform/resolvers/zod';
+import { useToggle } from '@uidotdev/usehooks';
+import mixpanel from 'mixpanel-browser';
+import Konva from 'konva';
+import { Artwork, Image as ImageType } from '@prisma/client';
+import Image from 'next/image';
+
+import { FrameObject, isFrameObject, isContainerObject } from '@/components/canvas/types';
+import { useFloatingElementPosition } from '@/hooks/use-floating-element-position';
+import { useHistoryState } from '@/hooks/use-history-state';
+import { isSingleFrameSelection, useSelectionState } from '@/hooks/use-selection-state';
+import { useCanvasTransformStore } from '@/store/canvas-transform-store';
+import { useImageDragStore } from '@/store/image-drag-store';
+import { useSelectionStore } from '@/store/selection-store';
+import { useCanvasStore } from '@/store/canvas-store';
+import useIsBanned from '@/hooks/use-is-banned';
+import { cn } from '@/lib/utils';
+import { triggerDownload } from '@/utils/download';
+import { exportFrameToDataUrl } from '@/utils/canvas/frame-export';
+import { validateFrameNsfw } from '@/utils/canvas/nsfw-validation';
+import { PublishArtworkFormValues, PublishArtworkSchema } from '@/schemas';
+import { createArtwork, generateArtworkDetails } from '@/actions/artwork';
+import { createArtworkAccessToken } from '@/actions/artwork-token';
+import { uploadImageBase64DirectToS3 } from '@/utils/client/image';
+import { isSimpleCanvasModeEnabled } from '@/lib/feature-flags';
+import { GAZAI_RECOMMENDATION_TAG } from '@/constants';
+import PublishDialog from '@/components/dialog/publish-dialog';
+import ShareDialog from '@/components/dialog/share-dialog';
+import {
+  AlertDialog,
+  AlertDialogFooter,
+  AlertDialogDescription,
+  AlertDialogContent,
+  AlertDialogHeader,
+  AlertDialogTitle,
+  AlertDialogAction
+} from '@/components/ui/alert-dialog';
+import {
+  DropdownMenu,
+  DropdownMenuTrigger,
+  DropdownMenuContent,
+  DropdownMenuItem,
+} from '@/components/ui/dropdown-menu';
+
+import { FrameDeleteDialog } from '../frame-delete-dialog';
+import { QuickActionButton } from './QuickActionButton';
+
+const IS_SIMPLE_CANVAS_MODE = isSimpleCanvasModeEnabled();
+
+const ASPECT_RATIOS = [
+  { labelKey: 'aspectRatioFree' as const, value: undefined },
+  { labelKey: 'aspectRatio16x9' as const, value: 16 / 9 },
+  { labelKey: 'aspectRatio4x3' as const, value: 4 / 3 },
+  { labelKey: 'aspectRatio1x1' as const, value: 1 },
+  { labelKey: 'aspectRatio9x16' as const, value: 9 / 16 }
+];
+
+export function FloatingFrameActions() {
+  const containerRef = useRef<HTMLDivElement>(null);
+  const t = useTranslations('Canvas');
+  const locale = useLocale();
+  const isReadOnly = useCanvasStore((state) => state.isReadOnly);
+  const stage = useCanvasStore((state) => state.stage);
+
+  // Selection state
+  const selection = useSelectionStore((state) => state.selection);
+  const { clearSelection } = useSelectionState();
+
+  // Canvas objects
+  const { canvasObjects, updateTempCanvasObjects, commitTempCanvasObjects } =
+    useHistoryState();
+
+  // Check if single frame is selected
+  const isSingleFrameSelected = isSingleFrameSelection(selection.selected);
+
+  // Get the selected frame object
+  const getSelectedFrame = useCallback((): FrameObject | undefined => {
+    if (!isSingleFrameSelected) return undefined;
+    const firstSelected = selection.selected[0];
+    if (!firstSelected) return undefined;
+    const obj = canvasObjects.find((o) => o.id === firstSelected.id);
+    return obj && isFrameObject(obj) ? obj : undefined;
+  }, [isSingleFrameSelected, selection.selected, canvasObjects]);
+
+  const selectedFrame = getSelectedFrame();
+
+  // TODO: Extract shared floating position + drag tracking logic into useFloatingActionPosition hook
+  // This pattern is duplicated in FloatingQuickActions.tsx
+  // Position hook -- anchor to top-center of the frame
+  const { updatePosition, updatePositionForObject } =
+    useFloatingElementPosition({
+      containerRef,
+      getTargetObject: getSelectedFrame,
+      anchor: 'top-center',
+      offset: { x: 0, y: -40 }
+    });
+
+  // Subscribe to canvas transform (zoom/pan)
+  const position = useCanvasTransformStore((state) => state.position);
+  const scale = useCanvasTransformStore((state) => state.scale);
+
+  useEffect(() => {
+    if (selectedFrame) {
+      updatePosition();
+    }
+  }, [position.x, position.y, scale, selectedFrame, updatePosition]);
+
+  // Subscribe to real-time drag/transform
+  const draggingImageId = useImageDragStore((state) => state.draggingImageId);
+  const dragPosition = useImageDragStore((state) => state.dragPosition);
+  const dragDimensions = useImageDragStore((state) => state.dragDimensions);
+  const dragScale = useImageDragStore((state) => state.dragScale);
+
+  const isDraggingThisObject =
+    draggingImageId && selectedFrame && draggingImageId === selectedFrame.id;
+
+  useEffect(() => {
+    if (selectedFrame && !isDraggingThisObject) {
+      updatePositionForObject(selectedFrame);
+    }
+  }, [
+    selectedFrame?.position.x,
+    selectedFrame?.position.y,
+    selectedFrame?.width,
+    selectedFrame?.height,
+    selectedFrame,
+    isDraggingThisObject,
+    updatePositionForObject
+  ]);
+
+  useEffect(() => {
+    if (
+      isDraggingThisObject &&
+      dragPosition &&
+      dragDimensions &&
+      selectedFrame
+    ) {
+      const tempObject = {
+        ...selectedFrame,
+        position: dragPosition,
+        width: dragDimensions.width,
+        height: dragDimensions.height,
+        scaleX: dragScale?.scaleX ?? selectedFrame.scaleX ?? 1,
+        scaleY: dragScale?.scaleY ?? selectedFrame.scaleY ?? 1
+      };
+      updatePositionForObject(tempObject);
+    }
+  }, [
+    isDraggingThisObject,
+    dragPosition,
+    dragDimensions,
+    dragScale,
+    selectedFrame,
+    updatePositionForObject
+  ]);
+
+  // Delete dialog state
+  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
+
+  // Publish state
+  const tGeneral = useTranslations();
+  const tError = useTranslations('errors');
+  const { isBanned, releaseAt } = useIsBanned();
+  const [isPending, startTransition] = useTransition();
+  const [privatePublish, setPrivatePublish] = useState(false);
+  const [isPublishDialogOpen, onTogglePublishDialog] = useToggle(false);
+  const [isShareDialogOpen, onToggleShareDialog] = useToggle(false);
+  const [nsfwDialogOpen, toggleNsfwDialog] = useToggle(false);
+  const [nsfwWords, setNsfwWords] = useState<string[]>([]);
+  const [publishedArtwork, setPublishedArtwork] = useState<
+    (Artwork & { image: (ImageType & { url: string }) | null }) | null
+  >(null);
+  const [accessToken, setAccessToken] = useState<string | null>(null);
+  const [framePreviewDataUrl, setFramePreviewDataUrl] = useState<string | null>(null);
+  const [framePreviewImageId, setFramePreviewImageId] = useState<string | null>(null);
+  const [isGeneratingDetails, setIsGeneratingDetails] = useState(false);
+  const hasAutoFilled = useRef(false);
+
+  const form = useForm<PublishArtworkFormValues>({
+    resolver: zodResolver(PublishArtworkSchema),
+    defaultValues: { name: '', description: '', tags: [] }
+  });
+
+  // --- Action handlers ---
+
+  // Shared helper: export frame with hidden border and selection frame
+  const exportFrameClean = useCallback(async (format: 'png' | 'jpg' = 'png'): Promise<string | null> => {
+    if (!selectedFrame || !stage) return null;
+    const group = stage.findOne<Konva.Group>(`#frame-${selectedFrame.id}`);
+    if (!group) return null;
+    const borderNode = group.findOne(`#${selectedFrame.id}-frame-border`);
+    borderNode?.visible(false);
+    const { setHideSelectionFrame } = useSelectionStore.getState();
+    setHideSelectionFrame(true);
+    try {
+      const frameBounds = {
+        x: selectedFrame.position.x,
+        y: selectedFrame.position.y,
+        width: selectedFrame.width,
+        height: selectedFrame.height
+      };
+      return await exportFrameToDataUrl(stage, frameBounds, format);
+    } finally {
+      borderNode?.visible(true);
+      setHideSelectionFrame(false);
+    }
+  }, [selectedFrame, stage]);
+
+  // Download handler
+  const handleFrameDownload = useCallback(
+    async (format: 'png' | 'jpg') => {
+      if (!selectedFrame || !stage) return;
+
+      toast.loading(t('frame.exporting'), { id: 'frame-export' });
+
+      try {
+        const dataUrl = await exportFrameClean(format);
+        if (!dataUrl) {
+          toast.error(t('frame.exportFailed'), { id: 'frame-export' });
+          return;
+        }
+
+        const ext = format === 'png' ? 'png' : 'jpg';
+        const filename = `${selectedFrame.name || 'frame'}-${selectedFrame.id.slice(0, 8)}.${ext}`;
+        triggerDownload(dataUrl, filename);
+        toast.success(t('frame.exportSuccess'), { id: 'frame-export' });
+
+        mixpanel.track('[Canvas] Frame exported', {
+          frameId: selectedFrame.id,
+          format
+        });
+      } catch {
+        toast.error(t('frame.exportFailed'), { id: 'frame-export' });
+      }
+    },
+    [selectedFrame, stage, t, exportFrameClean]
+  );
+
+  // Aspect ratio handler
+  const handleAspectRatioChange = useCallback(
+    (ratio: number | undefined) => {
+      if (!selectedFrame) return;
+
+      const newHeight =
+        ratio !== undefined
+          ? Math.round(selectedFrame.width / ratio)
+          : selectedFrame.height;
+
+      updateTempCanvasObjects((prev) =>
+        prev.map((obj) =>
+          obj.id === selectedFrame.id && isFrameObject(obj)
+            ? { ...obj, aspectRatio: ratio, height: newHeight }
+            : obj
+        )
+      );
+      commitTempCanvasObjects({
+        type: 'Changed Frame Aspect Ratio',
+        objectId: selectedFrame.id
+      });
+
+      mixpanel.track('[Canvas] Frame aspect ratio changed', {
+        frameId: selectedFrame.id,
+        ratio: ratio ?? 'free'
+      });
+    },
+    [selectedFrame, updateTempCanvasObjects, commitTempCanvasObjects]
+  );
+
+  // Delete handlers
+  const handleDeleteFrameOnly = useCallback(() => {
+    if (!selectedFrame) return;
+
+    updateTempCanvasObjects((prev) => {
+      // Clear parentId on children, then remove the frame itself
+      return prev
+        .map((obj) => {
+          if (
+            !isContainerObject(obj) &&
+            'parentId' in obj &&
+            obj.parentId === selectedFrame.id
+          ) {
+            return { ...obj, parentId: undefined };
+          }
+          return obj;
+        })
+        .filter((obj) => obj.id !== selectedFrame.id);
+    });
+
+    commitTempCanvasObjects({
+      type: 'Deleted Frame',
+      objectId: selectedFrame.id
+    });
+
+    clearSelection();
+
+    mixpanel.track('[Canvas] Frame deleted (frame only)', {
+      frameId: selectedFrame.id
+    });
+  }, [
+    selectedFrame,
+    updateTempCanvasObjects,
+    commitTempCanvasObjects,
+    clearSelection
+  ]);
+
+  const handleDeleteFrameAndContents = useCallback(() => {
+    if (!selectedFrame) return;
+
+    const childIds = new Set(selectedFrame.children);
+
+    updateTempCanvasObjects((prev) =>
+      prev.filter(
+        (obj) => obj.id !== selectedFrame.id && !childIds.has(obj.id)
+      )
+    );
+
+    commitTempCanvasObjects({
+      type: 'Deleted Frame and Contents',
+      objectId: selectedFrame.id
+    });
+
+    clearSelection();
+
+    mixpanel.track('[Canvas] Frame deleted (with contents)', {
+      frameId: selectedFrame.id,
+      childCount: childIds.size
+    });
+  }, [
+    selectedFrame,
+    updateTempCanvasObjects,
+    commitTempCanvasObjects,
+    clearSelection
+  ]);
+
+  const handleDeleteAction = useCallback(() => {
+    if (!selectedFrame) return;
+    if (selectedFrame.isLocked) return;
+
+    // If no children, delete immediately
+    if (selectedFrame.children.length === 0) {
+      handleDeleteFrameOnly();
+      return;
+    }
+
+    // Otherwise show dialog
+    setIsDeleteDialogOpen(true);
+  }, [selectedFrame, handleDeleteFrameOnly]);
+
+  // --- Publish handlers ---
+
+  const checkBanned = useCallback((): boolean => {
+    if (isBanned) {
+      toast.error(tError('userBanned', { releaseAt }));
+      return true;
+    }
+    return false;
+  }, [isBanned, releaseAt, tError]);
+
+  const handleFramePublish = useCallback(async () => {
+    if (checkBanned()) return;
+    if (!selectedFrame) return;
+
+    // Check for NSFW/CSAM content in frame images
+    const validation = validateFrameNsfw(selectedFrame, canvasObjects);
+    if (validation.isBlocked) {
+      setNsfwWords(validation.nsfwWords);
+      toggleNsfwDialog();
+      return;
+    }
+
+    if (!stage) return;
+
+    try {
+      const dataUrl = await exportFrameClean('png');
+      if (!dataUrl) {
+        toast.error(t('frame.exportFailed'));
+        return;
+      }
+
+      setFramePreviewDataUrl(dataUrl);
+      onTogglePublishDialog(true);
+
+      mixpanel.track('[Canvas] Frame Publish Dialog Opened', {
+        source: 'floating_frame_actions',
+        frameId: selectedFrame.id
+      });
+    } catch (error) {
+      console.error('Failed to export frame for publish:', error);
+      toast.error(t('frame.publishFailed'));
+    }
+  }, [checkBanned, selectedFrame, canvasObjects, stage, t, toggleNsfwDialog, onTogglePublishDialog, exportFrameClean]);
+
+  // Auto-fill form when dialog opens (only once per dialog open)
+  useEffect(() => {
+    if (!isPublishDialogOpen || !framePreviewDataUrl || hasAutoFilled.current)
+      return;
+
+    let cancelled = false;
+
+    const autoFillForm = async () => {
+      try {
+        hasAutoFilled.current = true;
+        setIsGeneratingDetails(true);
+
+        // Upload frame preview to S3 to get imageId
+        const uploadedImage = await uploadImageBase64DirectToS3(framePreviewDataUrl);
+
+        if (cancelled) return;
+
+        setFramePreviewImageId(uploadedImage.id);
+
+        // Generate artwork details using the uploaded image
+        const details = await generateArtworkDetails(uploadedImage.id, locale);
+
+        if (cancelled) return;
+
+        if (details.name || details.description || details.tags.length > 0) {
+          form.setValue('name', details.name || '');
+          if (details.description) {
+            form.setValue('description', details.description);
+          }
+          if (details.tags.length > 0) {
+            form.setValue('tags', details.tags);
+          }
+        }
+      } catch (error) {
+        if (!cancelled) {
+          console.error('Failed to auto-fill frame artwork details:', error);
+        }
+      } finally {
+        if (!cancelled) {
+          setIsGeneratingDetails(false);
+        }
+      }
+    };
+
+    autoFillForm();
+
+    return () => {
+      cancelled = true;
+    };
+  }, [isPublishDialogOpen, framePreviewDataUrl, form, locale]);
+
+  // Frame publish submit handler
+  const onFramePublish = useCallback((values: PublishArtworkFormValues) => {
+    if (!framePreviewDataUrl || !selectedFrame) return;
+
+    startTransition(async () => {
+      try {
+        // Reuse already-uploaded imageId if available, otherwise upload
+        const uploadedImage = framePreviewImageId
+          ? { id: framePreviewImageId }
+          : await uploadImageBase64DirectToS3(framePreviewDataUrl);
+
+        const baseTags = IS_SIMPLE_CANVAS_MODE
+          ? ['canvas', 'frame', GAZAI_RECOMMENDATION_TAG]
+          : ['canvas', 'frame'];
+        const allTags = values.tags
+          ? [...baseTags, ...values.tags.filter((tag) => !baseTags.includes(tag))]
+          : baseTags;
+
+        const payload = {
+          name: values.name,
+          description: values.description,
+          isPublic: !privatePublish,
+          isNsfw: false,
+          imageId: uploadedImage.id,
+          editedImageId: uploadedImage.id,
+          tags: allTags
+        };
+
+        const artwork = await createArtwork(payload);
+        if (privatePublish) {
+          const token = await createArtworkAccessToken({
+            artworkId: artwork.id
+          });
+          setAccessToken(token.token);
+        } else {
+          setAccessToken(null);
+        }
+        setPublishedArtwork(artwork);
+        onToggleShareDialog();
+
+        mixpanel.track('[Canvas] Frame published', {
+          artwork_name: values.name,
+          artwork_tags: values.tags,
+          artwork_description: values.description,
+          imageId: uploadedImage.id,
+          frameId: selectedFrame.id
+        });
+      } catch (error) {
+        console.error('Failed to publish frame:', error);
+        toast.error(t('frame.publishFailed'));
+        mixpanel.track('[Canvas] Frame publish failed', {
+          frameId: selectedFrame.id,
+          error: String(error)
+        });
+      } finally {
+        onTogglePublishDialog(false);
+        form.reset();
+      }
+    });
+  }, [framePreviewDataUrl, framePreviewImageId, privatePublish, selectedFrame, t, onTogglePublishDialog, onToggleShareDialog, form]);
+
+  const handleTogglePublishDialog = useCallback((open: boolean) => {
+    if (open && checkBanned()) return;
+    onTogglePublishDialog(open);
+    if (!open) {
+      form.reset();
+      setIsGeneratingDetails(false);
+      hasAutoFilled.current = false;
+      setFramePreviewDataUrl(null);
+      setFramePreviewImageId(null);
+    }
+  }, [checkBanned, onTogglePublishDialog, form]);
+
+  // Visibility
+  const visible =
+    isSingleFrameSelected &&
+    !!selectedFrame &&
+    !isReadOnly &&
+    !selectedFrame.isLocked;
+
+  if (!visible) return null;
+
+  return (
+    <>
+      <div
+        ref={containerRef}
+        className={cn(
+          'absolute z-20 pointer-events-auto',
+          'transition-opacity duration-150',
+          isDraggingThisObject ? 'opacity-50' : 'opacity-100'
+        )}
+        style={{ transform: 'translateX(-50%)' }}
+      >
+        <div
+          className={cn(
+            'flex items-center gap-0.5 rounded-lg shadow-lg p-1 transition-[background,backdrop-filter] duration-150',
+            'bg-background/80 backdrop-blur-md'
+          )}
+        >
+          {/* Download dropdown */}
+          <DropdownMenu>
+            <DropdownMenuTrigger asChild>
+              <QuickActionButton title={t('frame.download')}>
+                <Download size={16} />
+              </QuickActionButton>
+            </DropdownMenuTrigger>
+            <DropdownMenuContent align="start" sideOffset={4}>
+              <DropdownMenuItem onClick={() => handleFrameDownload('png')}>
+                {t('frame.downloadAsPng')}
+              </DropdownMenuItem>
+              <DropdownMenuItem onClick={() => handleFrameDownload('jpg')}>
+                {t('frame.downloadAsJpg')}
+              </DropdownMenuItem>
+            </DropdownMenuContent>
+          </DropdownMenu>
+
+          {/* Publish */}
+          <QuickActionButton
+            onClick={handleFramePublish}
+            title={t('frame.publish')}
+          >
+            <Share size={16} />
+          </QuickActionButton>
+
+          {/* Aspect ratio dropdown */}
+          <DropdownMenu>
+            <DropdownMenuTrigger asChild>
+              <QuickActionButton title={t('frame.aspectRatio')}>
+                <Frame size={16} />
+              </QuickActionButton>
+            </DropdownMenuTrigger>
+            <DropdownMenuContent align="center" sideOffset={4}>
+              {ASPECT_RATIOS.map((preset) => {
+                const isActive =
+                  selectedFrame?.aspectRatio === preset.value ||
+                  (selectedFrame?.aspectRatio === undefined &&
+                    preset.value === undefined);
+
+                return (
+                  <DropdownMenuItem
+                    key={preset.labelKey}
+                    onClick={() => handleAspectRatioChange(preset.value)}
+                    className="flex items-center justify-between"
+                  >
+                    <span>{t(`frame.${preset.labelKey}`)}</span>
+                    {isActive && <Check size={14} className="ml-2" />}
+                  </DropdownMenuItem>
+                );
+              })}
+            </DropdownMenuContent>
+          </DropdownMenu>
+
+          {/* Delete */}
+          <QuickActionButton
+            variant="danger"
+            onClick={handleDeleteAction}
+            title={t('quickActions.delete')}
+          >
+            <Trash2 size={16} />
+          </QuickActionButton>
+        </div>
+      </div>
+
+      <FrameDeleteDialog
+        isOpen={isDeleteDialogOpen}
+        onClose={() => setIsDeleteDialogOpen(false)}
+        onDeleteFrameOnly={() => {
+          handleDeleteFrameOnly();
+          setIsDeleteDialogOpen(false);
+        }}
+        onDeleteFrameAndContents={() => {
+          handleDeleteFrameAndContents();
+          setIsDeleteDialogOpen(false);
+        }}
+      />
+
+      {/* Frame Publish Dialog */}
+      <div data-testid="publish-dialog">
+        <PublishDialog
+          isPublishDialogOpen={isPublishDialogOpen}
+          onTogglePublishDialog={handleTogglePublishDialog}
+          preview={
+            framePreviewDataUrl ? (
+              <div className="relative h-fit rounded-md overflow-hidden">
+                <div className="-z-10 absolute top-0 left-0 w-full h-full bg-[linear-gradient(45deg,_#e5e7eb_25%,_transparent_25%,_transparent_75%,_#e5e7eb_75%,_#e5e7eb),_linear-gradient(45deg,_#e5e7eb_25%,_transparent_25%,_transparent_75%,_#e5e7eb_75%,_#e5e7eb)] bg-[size:20px_20px] bg-[position:0_0,_10px_10px]" />
+                <Image
+                  width={272}
+                  height={272}
+                  src={framePreviewDataUrl}
+                  alt="Frame preview"
+                  className="h-fit max-h-[308px] object-contain"
+                />
+              </div>
+            ) : null
+          }
+          isPending={isPending}
+          form={form}
+          privatePublish={privatePublish}
+          setPrivatePublish={setPrivatePublish}
+          onPublish={onFramePublish}
+          accessToken={accessToken}
+          hideTrigger
+          isGeneratingDetails={isGeneratingDetails}
+        />
+      </div>
+
+      {/* Share Dialog */}
+      <ShareDialog
+        open={isShareDialogOpen}
+        onOpenChange={onToggleShareDialog}
+        id={publishedArtwork?.id || ''}
+        image={publishedArtwork?.image?.url || ''}
+        type="image"
+        token={accessToken}
+      />
+
+      {/* NSFW Warning Dialog */}
+      <AlertDialog open={nsfwDialogOpen} onOpenChange={toggleNsfwDialog}>
+        <AlertDialogContent data-testid="nsfw-alert-dialog">
+          <AlertDialogHeader>
+            <AlertDialogTitle>
+              {tGeneral('tosViolation.nsfwPublish.title')}
+            </AlertDialogTitle>
+            <AlertDialogDescription>
+              {tGeneral('tosViolation.nsfwPublish.description', {
+                words: nsfwWords.join(', ')
+              })}
+            </AlertDialogDescription>
+          </AlertDialogHeader>
+          <AlertDialogFooter>
+            <AlertDialogAction>{tGeneral('OK')}</AlertDialogAction>
+          </AlertDialogFooter>
+        </AlertDialogContent>
+      </AlertDialog>
+    </>
+  );
+}
