diff --git a/components/canvas/konva/frame-node.tsx b/components/canvas/konva/frame-node.tsx
new file mode 100644
index 0000000..cd25b47
--- /dev/null
+++ b/components/canvas/konva/frame-node.tsx
@@ -0,0 +1,457 @@
+import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
+import Konva from 'konva';
+import { Group, Rect, Transformer } from 'react-konva';
+
+import { useSelectionBasic } from '@/hooks/use-selection-state';
+
+import {
+  CanvasObject,
+  FrameObject,
+  isImageObject,
+  isTextObject,
+  isShapeObject,
+  isToneObject,
+  isVideoObject,
+  ImageObject,
+  ShapeType,
+  ToneType,
+  TextObject
+} from '../types';
+
+import { ImageNode, InpaintImageNode } from './image-node';
+import SpeechBubble from './speech-bubble';
+import ShapeNode from './shape-node';
+import ToneNode from './tone-node';
+import VideoNode from './video-node';
+
+const FRAME_BORDER_RADIUS = 24;
+const FRAME_BORDER_WIDTH = 8;
+const FRAME_BORDER_COLOR = '#bbb';
+const SELECTION_COLOR = '#2563eb';
+
+interface FrameNodeProps {
+  frame: FrameObject;
+  isSelected: boolean;
+  isChildrenSelected: boolean;
+  canvasObjects: CanvasObject[];
+  selectImage: (id: string) => void;
+  selectText: (id: string) => void;
+  selectShape: (id: string, shapeType: ShapeType) => void;
+  selectTone: (id: string, toneType: ToneType) => void;
+  selectVideo: (id: string) => void;
+  handleTextUpdate: (textId: string, updates: Partial<TextObject>) => void;
+  isReadOnly: boolean;
+  selectedTool: string;
+  showTransformer?: boolean;
+  // NOTE: Interface changed — now passes computed absolute position as second arg.
+  // Parent handler (handleFrameTransformEnd in gazai-canvas.tsx) should use
+  // absolutePosition instead of reading node.x()/node.y() directly.
+  onChildDragEnd?: (childId: string, newAbsolutePosition: { x: number; y: number }) => void;
+  onTransformEnd?: (e: Konva.KonvaEventObject<Event>, absolutePosition: { x: number; y: number }) => void;
+  onBackgroundClick?: () => void;
+}
+
+export const FrameNode: React.FC<FrameNodeProps> = ({
+  frame,
+  isSelected,
+  isChildrenSelected,
+  canvasObjects,
+  selectImage,
+  selectText,
+  selectShape,
+  selectTone,
+  selectVideo,
+  handleTextUpdate,
+  isReadOnly,
+  selectedTool,
+  showTransformer,
+  onChildDragEnd,
+  onTransformEnd,
+  onBackgroundClick
+}) => {
+  const {
+    isSelected: isObjectSelected,
+    hideSelectionFrame,
+    selection
+  } = useSelectionBasic();
+
+  const groupRef = useRef<Konva.Group>(null);
+  const clipGroupRef = useRef<Konva.Group>(null);
+  const borderRef = useRef<Konva.Rect>(null);
+  const transformerRef = useRef<Konva.Transformer>(null);
+
+  const isMultiSelect = selection.selected.length > 1;
+  const shouldClip = frame.clipContent !== false;
+  const [isDraggingChild, setIsDraggingChild] = useState(false);
+
+  // PERF-001: Pre-build O(1) lookup maps instead of O(n) find/filter per child
+  const childMap = useMemo(() => {
+    const map = new Map<string, CanvasObject>();
+    for (const obj of canvasObjects) {
+      map.set(obj.id, obj);
+    }
+    return map;
+  }, [canvasObjects]);
+
+  const inpaintChildMap = useMemo(() => {
+    const map = new Map<string, ImageObject[]>();
+    // Build reverse lookup: childId -> parentId (single pass)
+    const childToParent = new Map<string, string>();
+    for (const obj of canvasObjects) {
+      if (isImageObject(obj) && obj.children) {
+        for (const childId of obj.children) {
+          childToParent.set(childId, obj.id);
+        }
+      }
+    }
+    // Assign visible image children to their parent (single pass)
+    for (const obj of canvasObjects) {
+      if (isImageObject(obj) && obj.visible) {
+        const parentId = childToParent.get(obj.id);
+        if (parentId) {
+          const existing = map.get(parentId) || [];
+          existing.push(obj);
+          map.set(parentId, existing);
+        }
+      }
+    }
+    return map;
+  }, [canvasObjects]);
+
+  // PERF-003: Stable click handler for common child types (image, text, video)
+  const handleChildClick = useCallback(
+    (childId: string, isLocked: boolean | undefined, type: 'image' | 'text' | 'video') => {
+      if (isLocked) return;
+      switch (type) {
+        case 'image': selectImage(childId); break;
+        case 'text': selectText(childId); break;
+        case 'video': selectVideo(childId); break;
+      }
+    },
+    [selectImage, selectText, selectVideo]
+  );
+
+  // Disable clip on drag start so the child (and its Transformer) can
+  // render outside the frame boundary during drag.
+  const handleChildDragStart = useCallback(
+    (e: Konva.KonvaEventObject<DragEvent>) => {
+      e.cancelBubble = true;
+      setIsDraggingChild(true);
+    },
+    []
+  );
+
+  // On drag end, restore clip and update position/containment.
+  const createChildDragEnd = useCallback(
+    (childId: string, selectFn: (id: string) => void) =>
+      (e: Konva.KonvaEventObject<DragEvent>) => {
+        setIsDraggingChild(false);
+        const node = e.target;
+        const newAbsolutePosition = {
+          x: node.x() + frame.position.x,
+          y: node.y() + frame.position.y
+        };
+        onChildDragEnd?.(childId, newAbsolutePosition);
+        selectFn(childId);
+      },
+    [frame.position.x, frame.position.y, onChildDragEnd]
+  );
+
+  useEffect(() => {
+    if (!showTransformer || !transformerRef.current || !borderRef.current) {
+      return;
+    }
+    // Attach Transformer to the border Rect (not the Group) so handles
+    // match frame dimensions even when children extend beyond the frame.
+    transformerRef.current.nodes([borderRef.current]);
+    transformerRef.current.moveToTop();
+    transformerRef.current.getLayer()?.batchDraw();
+  }, [showTransformer]);
+
+  return (
+    <>
+    <Group
+      ref={groupRef}
+      id={`frame-${frame.id}`}
+      x={frame.position.x}
+      y={frame.position.y}
+      width={frame.width}
+      height={frame.height}
+    >
+      {/* Clipped group for background + children — use explicit clip rect
+          so Konva can compute correct getClientRect() bounds for Transformer */}
+      <Group
+        ref={clipGroupRef}
+        {...(shouldClip && !isDraggingChild && {
+          clipX: 0,
+          clipY: 0,
+          clipWidth: frame.width,
+          clipHeight: frame.height
+        })}
+      >
+        {/* Frame background — listen when it has a visible fill or when
+            the frame is selected (so interior clicks can deselect it
+            and drag can be initiated from anywhere inside the frame) */}
+        <Rect
+          id={`${frame.id}-frame-background`}
+          width={frame.width}
+          height={frame.height}
+          fill={frame.fillColor || 'transparent'}
+          listening={!!frame.fillColor || isSelected}
+          {...(isSelected && onBackgroundClick && {
+            onClick: onBackgroundClick
+          })}
+        />
+
+        {/* Render children */}
+        {frame.children.map((childId) => {
+          const child = childMap.get(childId);
+          if (!child) return null;
+          if (!child.visible) return null;
+
+          // Children positions are absolute; offset relative to frame
+          const offsetX = -frame.position.x;
+          const offsetY = -frame.position.y;
+
+          if (isImageObject(child)) {
+            const isThisSelected = isObjectSelected(child.id);
+            const computedDraggable =
+              selectedTool === 'select' && !child.isLocked && !isReadOnly;
+            const computedShowTransformer =
+              isThisSelected &&
+              !child.isLocked &&
+              !isMultiSelect &&
+              !hideSelectionFrame &&
+              !isReadOnly;
+
+            return (
+              <ImageNode
+                key={child.id}
+                id={child.id}
+                src={
+                  Array.isArray(child.src)
+                    ? child.src[child.currentIndex || 0]
+                    : child.src
+                }
+                position={{
+                  x: child.position.x + offsetX,
+                  y: child.position.y + offsetY
+                }}
+                width={child.width}
+                height={child.height}
+                rotation={child.rotation}
+                scaleX={child.scaleX}
+                scaleY={child.scaleY}
+                isSelected={!child.isLocked && isThisSelected}
+                isMultiSelect={isMultiSelect}
+                draggable={computedDraggable}
+                showTransformer={computedShowTransformer}
+                opacity={1}
+                onClick={() => handleChildClick(child.id, child.isLocked, 'image')}
+                onDragStart={handleChildDragStart}
+                onDragEnd={createChildDragEnd(child.id, selectImage)}
+              >
+                {(inpaintChildMap.get(child.id) || []).map((inpaintChild) => (
+                    <InpaintImageNode
+                      key={inpaintChild.id}
+                      id={inpaintChild.id}
+                      src={
+                        Array.isArray(inpaintChild.src)
+                          ? inpaintChild.src[inpaintChild.currentIndex || 0]
+                          : inpaintChild.src
+                      }
+                      position={inpaintChild.position}
+                      width={inpaintChild.width}
+                      height={inpaintChild.height}
+                    />
+                  ))}
+              </ImageNode>
+            );
+          } else if (isTextObject(child)) {
+            return (
+              <SpeechBubble
+                key={child.id}
+                id={child.id}
+                text={child.text}
+                x={child.position.x + offsetX}
+                y={child.position.y + offsetY}
+                width={child.width}
+                height={child.height}
+                fontSize={child.fontSize}
+                fontFamily={child.fontFamily}
+                textColor={child.textColor}
+                textAlign={child.textAlign}
+                textOrientation={child.textOrientation}
+                isBold={child.isBold}
+                isItalic={child.isItalic}
+                isUnderline={child.isUnderline}
+                bubbleStyle={child.bubbleStyle}
+                bubbleColor={child.bubbleColor}
+                bubbleStrokeWidth={child.bubbleStrokeWidth}
+                bubbleStrokeColor={child.bubbleStrokeColor}
+                bubblePadding={child.bubblePadding}
+                rotation={child.rotation}
+                opacity={1}
+                draggable={selectedTool === 'select' && !child.isLocked && !isReadOnly}
+                onClick={() => handleChildClick(child.id, child.isLocked, 'text')}
+                onDragStart={handleChildDragStart}
+                onDragEnd={createChildDragEnd(child.id, selectText)}
+                isSelected={isObjectSelected(child.id)}
+                tail={child.tail}
+                onUpdateText={handleTextUpdate}
+              />
+            );
+          } else if (isShapeObject(child)) {
+            return (
+              <ShapeNode
+                key={child.id}
+                shape={{
+                  ...child,
+                  position: {
+                    x: child.position.x + offsetX,
+                    y: child.position.y + offsetY
+                  }
+                }}
+                isSelected={isObjectSelected(child.id)}
+                draggable={selectedTool === 'select' && !child.isLocked && !isReadOnly}
+                opacity={1}
+                onClick={() => {
+                  if (!child.isLocked) {
+                    selectShape(child.id, child.shapeType);
+                  }
+                }}
+                onDragStart={handleChildDragStart}
+                onDragEnd={createChildDragEnd(child.id, (id) => selectShape(id, child.shapeType))}
+              />
+            );
+          } else if (isToneObject(child)) {
+            return (
+              <ToneNode
+                key={child.id}
+                tone={{
+                  ...child,
+                  position: {
+                    x: child.position.x + offsetX,
+                    y: child.position.y + offsetY
+                  }
+                }}
+                isSelected={isObjectSelected(child.id)}
+                isMultiSelect={isMultiSelect}
+                draggable={selectedTool === 'select' && !child.isLocked && !isReadOnly}
+                opacity={1}
+                showTransformer={
+                  isObjectSelected(child.id) &&
+                  !isMultiSelect &&
+                  !hideSelectionFrame
+                }
+                onClick={() => {
+                  if (!child.isLocked) {
+                    selectTone(child.id, child.toneType);
+                  }
+                }}
+                onDragStart={handleChildDragStart}
+                onDragEnd={createChildDragEnd(child.id, (id) => selectTone(id, child.toneType))}
+              />
+            );
+          } else if (isVideoObject(child)) {
+            return (
+              <VideoNode
+                key={child.id}
+                id={child.id}
+                video={child}
+                isSelected={isObjectSelected(child.id)}
+                isMultiSelect={isMultiSelect}
+                draggable={selectedTool === 'select' && !child.isLocked && !isReadOnly}
+                showTransformer={
+                  isObjectSelected(child.id) &&
+                  !child.isLocked &&
+                  !isMultiSelect &&
+                  !hideSelectionFrame &&
+                  !isReadOnly
+                }
+                onClick={() => handleChildClick(child.id, child.isLocked, 'video')}
+                onDragStart={handleChildDragStart}
+                onDragEnd={createChildDragEnd(child.id, selectVideo)}
+              />
+            );
+          }
+
+          return null;
+        })}
+      </Group>
+
+      {/* Frame border — outside clip group so stroke is fully visible */}
+      <Rect
+        ref={borderRef}
+        id={`${frame.id}-frame-border`}
+        width={frame.width}
+        height={frame.height}
+        cornerRadius={FRAME_BORDER_RADIUS}
+        stroke={
+          isSelected && !hideSelectionFrame
+            ? SELECTION_COLOR
+            : FRAME_BORDER_COLOR
+        }
+        strokeWidth={FRAME_BORDER_WIDTH}
+        listening={!isChildrenSelected}
+        hitStrokeWidth={10}
+        hitFunc={(ctx, shape) => {
+          const w = shape.width();
+          const h = shape.height();
+          const margin = 10;
+          ctx.beginPath();
+          // Outer rect
+          ctx.moveTo(-margin, -margin);
+          ctx.lineTo(w + margin, -margin);
+          ctx.lineTo(w + margin, h + margin);
+          ctx.lineTo(-margin, h + margin);
+          ctx.closePath();
+          // Inner rect (hole) — makes interior non-hittable
+          ctx.moveTo(margin, margin);
+          ctx.lineTo(margin, h - margin);
+          ctx.lineTo(w - margin, h - margin);
+          ctx.lineTo(w - margin, margin);
+          ctx.closePath();
+          ctx.fillStrokeShape(shape);
+        }}
+      />
+    </Group>
+
+    {/* Frame resize transformer */}
+    {showTransformer && !isMultiSelect && (
+      <Transformer
+        ref={transformerRef}
+        id={`transformer-frame-${frame.id}`}
+        boundBoxFunc={(oldBox, newBox) => {
+          if (newBox.width < 50 || newBox.height < 50) {
+            return oldBox;
+          }
+          return newBox;
+        }}
+        rotateEnabled={false}
+        resizeEnabled={true}
+        keepRatio={frame.aspectRatio != null}
+        anchorStroke={SELECTION_COLOR}
+        anchorFill="#ffffff"
+        anchorSize={8}
+        borderStroke="transparent"
+        borderStrokeWidth={0}
+        onTransformEnd={(e) => {
+          // CR-001: Compute absolute position without mutating the Konva node.
+          // The absolute coords are passed as a second argument so the parent
+          // handler doesn't depend on in-place mutation timing.
+          const node = e.target;
+          const absX = frame.position.x + node.x();
+          const absY = frame.position.y + node.y();
+          onTransformEnd?.(e, { x: absX, y: absY });
+          // Reset local position — React will re-render with new props
+          node.x(0);
+          node.y(0);
+        }}
+      />
+    )}
+    </>
+  );
+};
+
+export default FrameNode;
