diff --git a/components/canvas/frame-name-label.tsx b/components/canvas/frame-name-label.tsx
new file mode 100644
index 0000000..2052b2a
--- /dev/null
+++ b/components/canvas/frame-name-label.tsx
@@ -0,0 +1,118 @@
+'use client';
+
+import { useState, useRef, useEffect, useCallback } from 'react';
+
+import { useImageDragStore } from '@/store/image-drag-store';
+
+import { FrameObject } from './types';
+
+interface FrameNameLabelProps {
+  frame: FrameObject;
+  stagePosition: { x: number; y: number };
+  scale: number;
+  onNameChange: (frameId: string, newName: string) => void;
+}
+
+export function FrameNameLabel({
+  frame,
+  stagePosition,
+  scale,
+  onNameChange
+}: FrameNameLabelProps) {
+  const [isEditing, setIsEditing] = useState(false);
+  const [editValue, setEditValue] = useState(frame.name);
+  const inputRef = useRef<HTMLInputElement>(null);
+
+  // Subscribe to drag position only when this specific frame is being dragged.
+  // Using a derived selector avoids re-rendering all labels when any frame is dragged.
+  const dragData = useImageDragStore((state) =>
+    state.draggingImageId === frame.id
+      ? { isDragging: true, position: state.dragPosition }
+      : null
+  );
+  const isDraggingThisFrame = dragData !== null;
+  const effectivePosition = dragData?.position ?? frame.position;
+
+  // Convert canvas coordinates to screen coordinates
+  const screenX = effectivePosition.x * scale + stagePosition.x;
+  const screenY = effectivePosition.y * scale + stagePosition.y;
+
+  // Position label above the top-left of the frame
+  const labelY = screenY - 24;
+
+  useEffect(() => {
+    if (isEditing && inputRef.current) {
+      inputRef.current.focus();
+      inputRef.current.select();
+    }
+  }, [isEditing]);
+
+  // Sync edit value when frame name changes externally
+  useEffect(() => {
+    if (!isEditing) {
+      setEditValue(frame.name);
+    }
+  }, [frame.name, isEditing]);
+
+  const commitEdit = useCallback(() => {
+    const trimmed = editValue.trim();
+    if (trimmed && trimmed !== frame.name) {
+      onNameChange(frame.id, trimmed);
+    } else {
+      setEditValue(frame.name);
+    }
+    setIsEditing(false);
+  }, [editValue, frame.name, frame.id, onNameChange]);
+
+  const cancelEdit = useCallback(() => {
+    setEditValue(frame.name);
+    setIsEditing(false);
+  }, [frame.name]);
+
+  const handleDoubleClick = useCallback(() => {
+    setEditValue(frame.name);
+    setIsEditing(true);
+  }, [frame.name]);
+
+  const handleKeyDown = useCallback(
+    (e: React.KeyboardEvent<HTMLInputElement>) => {
+      e.stopPropagation();
+      if (e.key === 'Enter') {
+        commitEdit();
+      } else if (e.key === 'Escape') {
+        cancelEdit();
+      }
+    },
+    [commitEdit, cancelEdit]
+  );
+
+  return (
+    <div
+      className="absolute z-10 pointer-events-auto"
+      style={{
+        left: screenX,
+        top: labelY,
+        transform: 'translateY(-100%)'
+      }}
+    >
+      {isEditing ? (
+        <input
+          ref={inputRef}
+          className="bg-background/60 backdrop-blur-sm rounded px-2 py-0.5 text-xs text-foreground outline-none border border-border/50 min-w-[60px]"
+          value={editValue}
+          onChange={(e) => setEditValue(e.target.value)}
+          onBlur={commitEdit}
+          onKeyDown={handleKeyDown}
+        />
+      ) : (
+        <span
+          className="rounded px-1 py-0.5 cursor-default select-none"
+          style={{ color: '#999', fontSize: '14px', lineHeight: '1.25' }}
+          onDoubleClick={handleDoubleClick}
+        >
+          {frame.name}
+        </span>
+      )}
+    </div>
+  );
+}
